command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: FARBENSPIEL (V13 Ready - mit EffektEnde)
// ==========================================

(async () => {
    // ============================================================
    // 0. Framework laden & Prüfungen
    // ============================================================
    const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (fwMacro) { await fwMacro.execute(); }

    if (typeof DSK === "undefined") {
        ui.notifications.error("Das DSK-Framework konnte nicht geladen werden!");
        return;
    }
    const DSK_FW = globalThis.DSK || DSK;

    const gabenName = "Farbenspiel";
    const ahne = "Aphasma";
    const finalEffektName = `${gabenName} (${ahne})`;

    // Hilfsfunktion: Finde alle Spieler-IDs, denen ein Akteur gehört
    const getOwners = (act) => {
        if (!act) return [];
        const ownership = act.ownership || act.permission || {};
        return Object.entries(ownership)
            .filter(([id, lvl]) => lvl === 3 && id !== "default")
            .map(([id]) => id);
    };

    if (DSK_FW.EffektEnde) {
        DSK_FW.EffektEnde.Register(
            "aphasmaFarbenspiel", 
            finalEffektName, 
            "Die Illusion verblasst, und man nimmt seine wahre Gestalt wieder an."
        );
    }

    const casterActor = (typeof testData !== "undefined" && testData?.actor) || 
                        (typeof testData !== "undefined" && testData?.speaker?.actor ? game.actors.get(testData.speaker.actor) : null) || 
                        (typeof testData !== "undefined" && testData?.speaker?.token ? canvas.tokens.get(testData.speaker.token)?.actor : null) || 
                        actor || 
                        canvas.tokens.controlled[0]?.actor || 
                        game.user.character;

    if (!casterActor) {
        ui.notifications.warn("Wirkender konnte nicht ermittelt werden!");
        return;
    }

    // QS aus dem Flag auslesen, das vom Start-Makro gesetzt wurde (mit Fallback)
    let qsWert = casterActor.getFlag("world", "letzteGabenQS") || 1;
    if (casterActor.getFlag("world", "letzteGabenQS")) {
        await casterActor.unsetFlag("world", "letzteGabenQS");
    }

    try {
        if (typeof testData !== "undefined" && testData) {
            const parsedQs = Number(testData?.result?.QL || testData?.qualityStep);
            if (!isNaN(parsedQs) && parsedQs > 0) {
                qsWert = parsedQs;
            }
        }
    } catch (e) {}

    if (qsWert <= 0) {
        return ui.notifications.warn("Die Probe ist fehlgeschlagen.");
    }

    const targetName = DSK_FW.ResolveTokenName(casterActor);
    const basisBeschreibung = `Mit dieser Gabe kann die Färbung des Fells verändert werden, sowohl komplett als auch in Teilen. Die Illusion hält an, bis die Gabe erneut eingesetzt wird.`;
    const dauerText = "Permanent (bis zur Neunutzung)";

    // Wesen prüfen
    let istGueltig = DSK_FW.Effekt.CheckTarget(casterActor, "lebewesen") || 
                       DSK_FW.Effekt.CheckTarget(casterActor, "erwachte") || 
                       casterActor.type === "character" || 
                       casterActor.type === "npc";

    if (DSK_FW.Effekt.CheckTarget(casterActor, "geist") || DSK_FW.Effekt.CheckTarget(casterActor, "untot")) {
        istGueltig = false;
    }

    if (!istGueltig) {
        let ownerIds = new Set(game.users.filter(u => u.isGM).map(u => u.id));
        getOwners(casterActor).forEach(id => ownerIds.add(id));

        ChatMessage.create({
            speaker: { alias: "System" },
            whisper: Array.from(ownerIds).filter(id => game.users.get(id)),
            content: `
                <div style="font-family: 'Signika', sans-serif;">
                    ${DSK_FW.UI.Header(gabenName, DSK_FW.Symbol(ahne))}
                    <div class="dskbox2" style="margin-top:10px;">
                        <p style="color:#B30000; font-weight:bold;">Fehlschlag: Ungültiges Zielwesen für Farbenspiel.</p>
                    </div>
                </div>
            `
        });
        return;
    }

    try {
        // ============================================================
        // 1. UNSICHTBAREN EFFEKT ANLEGEN ODER AKTUALISIEREN
        // ============================================================
        let bestehenderEffekt = casterActor.effects.find(e => e.name === finalEffektName);

        if (bestehenderEffekt) {
            await bestehenderEffekt.update({
                description: basisBeschreibung,
                disabled: false
            });
        } else {
            const effektDaten = {
                name: finalEffektName,
                img: DSK_FW.Symbol(ahne),
                type: "base",
                system: {},
                changes: [],
                disabled: false,
                origin: casterActor.uuid,
                description: basisBeschreibung,
                flags: {
                    dsk: {
                        value: null,
                        description: "",
                        auto: null,
                        manual: 0,
                        hideOnToken: true,
                        hidePlayers: true,
                        onRemove: ""
                    }
                }
            };
            await casterActor.createEmbeddedDocuments("ActiveEffect", [effektDaten]);
        }

        // ============================================================
        // 2. WHISPER-EMPFÄNGER & CHATKARTE (System-Sprecher)
        // ============================================================
        let ownerIds = new Set(game.users.filter(u => u.isGM).map(u => u.id));
        getOwners(casterActor).forEach(id => ownerIds.add(id));
        const whisperEmpfaenger = Array.from(ownerIds).filter(id => game.users.get(id));

        const erfolgHtml = `
            <div style="margin-top: 10px; margin-bottom: 10px;">
                <p style="margin-bottom: 5px;"><span style="color:#18940F; font-weight:bold;">Erfolg</span></p>
                <ul class="dsklist" style="margin-top:0; font-weight:normal;">
                    <li>${targetName}</li>
                </ul>
            </div>
        `;

        await ChatMessage.create({
            speaker: { alias: "System" },
            whisper: whisperEmpfaenger,
            content: `
                <div style="font-family: 'Signika', sans-serif;">
                    ${DSK_FW.UI.Header(gabenName, DSK_FW.Symbol(ahne))}
                    <div class="dskbox2" style="margin-top:10px;">
                        <p><b>Gabenwirkung:</b></p>
                        <p>${basisBeschreibung}</p>
                        <hr>
                        ${erfolgHtml}
                        <hr>
                        <p style="text-align:center; font-weight:bold;">
                            Wirkungsdauer:<br>${dauerText}
                        </p>
                    </div>
                </div>
            `
        });

    } catch (e) {
        console.warn(`Farbenspiel konnte für ${targetName} nicht angewendet werden:`, e);
    }
})();
